#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_WORDS 5000
#define MAX_LEN 11

// Queue for BFS
typedef struct {
    int data[MAX_WORDS];
    int front, rear;
} Queue;

void q_init(Queue* q) {
    q->front = 0;
    q->rear = 0;
}

bool q_empty(Queue* q) {
    return q->front == q->rear;
}

void q_push(Queue* q, int val) {
    q->data[q->rear++] = val;
}

int q_pop(Queue* q) {
    return q->data[q->front++];
}

// Check if two words differ by exactly one letter
bool oneLetterDiff(char* a, char* b) {
    int diff = 0;
    for (int i = 0; a[i]; i++) {
        if (a[i] != b[i]) {
            diff++;
            if (diff > 1) return false;
        }
    }
    return diff == 1;
}

int ladderLength(char * beginWord, char * endWord, char ** wordList, int wordListSize){
    // Check if endWord is in wordList
    int endIndex = -1;
    for (int i = 0; i < wordListSize; i++) {
        if (strcmp(wordList[i], endWord) == 0) {
            endIndex = i;
            break;
        }
    }
    if (endIndex == -1) return 0;

    // If beginWord is not in wordList, add it at the end for convenience
    // We'll create a new array of words including beginWord
    char* words[MAX_WORDS+1];
    int n = wordListSize;
    bool beginInList = false;
    for (int i = 0; i < wordListSize; i++) {
        words[i] = wordList[i];
        if (strcmp(wordList[i], beginWord) == 0) beginInList = true;
    }
    if (!beginInList) {
        words[n++] = beginWord;
    }

    // BFS initialization
    // visited array for all words
    bool visited[MAX_WORDS+1];
    memset(visited, 0, sizeof(visited));

    // Find index of beginWord in words array
    int beginIndex = -1;
    for (int i = 0; i < n; i++) {
        if (strcmp(words[i], beginWord) == 0) {
            beginIndex = i;
            break;
        }
    }

    Queue q;
    q_init(&q);
    q_push(&q, beginIndex);
    visited[beginIndex] = true;

    int dist[MAX_WORDS+1];
    for (int i = 0; i < n; i++) dist[i] = 0;
    dist[beginIndex] = 1;

    while (!q_empty(&q)) {
        int cur = q_pop(&q);
        if (strcmp(words[cur], endWord) == 0) {
            return dist[cur];
        }
        for (int i = 0; i < n; i++) {
            if (!visited[i] && oneLetterDiff(words[cur], words[i])) {
                visited[i] = true;
                dist[i] = dist[cur] + 1;
                q_push(&q, i);
            }
        }
    }
    return 0;
}

